# Shared paths for the on-device rig scripts. Sourced by the other scripts.

# Device-side configuration generated by deploy.sh from phone.env and deployed
# alongside these scripts. Deriving the path from this script avoids a circular
# dependency on RIG_DIR when that value is customised.
RIG_ENV=${RIG_ENV:-$(CDPATH= cd -- "$(dirname "$0")" && pwd)/rig.env}
[ -f "$RIG_ENV" ] && . "$RIG_ENV"

RIG_DIR=${RIG_DIR:-/data/local/tmp/scourge}
BIN=${BIN:-$RIG_DIR/phone-rig}
CFG=${CFG:-$RIG_DIR/config.json}
LOG=${LOG:-$RIG_DIR/live.log}
AUTO_FLAG=${AUTO_FLAG:-/data/local/tmp/scourge_auto}
GADGET_DIR=${GADGET_DIR:-/config/usb_gadget/g1}
UDC=${UDC:-}
MASS_STORAGE_FN=${MASS_STORAGE_FN:-mass_storage.0}
CONFIG_NAME=${CONFIG_NAME:-c.1}
LUN_NAME=${LUN_NAME:-lun.0}
DM_NAME=${DM_NAME:-}

need_root() {
    [ "$(id -u)" = 0 ] || { echo "run under su -c" >&2; return 1; }
    [ -x "$BIN" ] || { echo "$BIN missing or not executable" >&2; return 1; }
    [ -f "$CFG" ] || { echo "$CFG missing" >&2; return 1; }
}

dm_name() {
    if [ -n "$DM_NAME" ]; then
        echo "$DM_NAME"
    else
        sed -n 's/.*"dmname"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$CFG" | head -1
    fi
}

# Convert a block node path (or MAJ:MIN) into the MAJ:MIN form dm-linear uses.
dev_arg() {
    p=$1
    case "$p" in
        *:*) echo "$p"; return 0 ;;
    esac
    n=$(basename "$p")
    if [ -f "/sys/block/$n/dev" ]; then
        cat "/sys/block/$n/dev"
        return 0
    fi
    return 1
}

# Android's ueventd creates /dev/block/dm-N; /dev/mapper is a udev convention
# and is normally absent. Resolve by scanning sysfs for the dm device name.
dm_node_for() {
    name=${1:-}
    [ -n "$name" ] || return 1
    for s in /sys/block/dm-*/dm/name; do
        [ -f "$s" ] || continue
        if [ "$(cat "$s" 2>/dev/null)" = "$name" ]; then
            node=/dev/block/$(basename "$(dirname "$(dirname "$s")")")
            [ -b "$node" ] || return 1
            echo "$node"
            return 0
        fi
    done
    return 1
}

stop_watchers() {
    for c in /proc/[0-9]*/cmdline; do
        if grep -aq 'phone-ri[g]' "$c" 2>/dev/null; then
            p=${c#/proc/}; p=${p%/cmdline}
            [ "$p" = "$$" ] || kill "$p" 2>/dev/null
        fi
    done
    sleep 1
}
